1	import { redirect, notFound } from "next/navigation";
2	import { headers } from "next/headers";
3	import { realUser, impersonating } from "@/lib/auth";
4	import { GRANTABLE_AREAS, listGrantedAreas } from "@/lib/staff-grants";
5	import { staffIpBlocked } from "@/lib/staff-ip";
6	import { db } from "@/lib/db";
7	import { getSettingBool } from "@/lib/settings";
8	import { Shell, type NavSection } from "@/components/portal/Shell";
9	
10	/**
11	 * Host gate: the employee portal is only reachable from the dedicated staff
12	 * hostname(s) in NXEON_STAFF_HOSTS (comma-separated) — same shape as
13	 * app/admin/layout.tsx's adminHostBlocked, deliberately kept a separate env
14	 * var so the two portals can live on different hosts independently. On any
15	 * other host, /staff 404s as if it doesn't exist. Empty/unset = no host
16	 * restriction (dev fallback).
17	 */
18	async function staffHostBlocked(): Promise<boolean> {
19	  const allow = (process.env.NXEON_STAFF_HOSTS ?? "")
20	    .split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
21	  if (allow.length === 0) return false;
22	  const host = ((await headers()).get("host") ?? "").toLowerCase().split(":")[0];
23	  return !allow.includes(host);
24	}
25	
26	/** Leading nav icon (key into components/portal/Shell.tsx's `icons` map) per grantable area. */
27	const AREA_ICONS: Record<string, string> = {
28	  supportTickets: "lifebuoy",
29	  liveChat: "chat",
30	  redditTemplates: "content",
31	  companyInbox: "mail",
32	  companyMailboxes: "db",
33	  clientsBasic: "users",
34	  tasks: "queue",
35	};
36	
37	export default async function StaffLayout({ children }: { children: React.ReactNode }) {
38	  // Wrong host (e.g. the public site or the admin host) → 404, so /staff isn't
39	  // reachable there.
40	  if (await staffHostBlocked()) notFound();
41	
42	  const user = await realUser();
43	  if (!user) redirect("/login");
44	  // EMPLOYEE is this portal's real audience. ADMIN is let in too, deliberately:
45	  // it lets the owner log in and see exactly what a given employee's grants
46	  // produce before handing them out. Every other role (SUPPORT/BILLING/CUSTOMER)
47	  // keeps going exactly where it already does — this portal has nothing for them.
48	  if (user.role !== "EMPLOYEE" && user.role !== "ADMIN") redirect("/dashboard");
49	  const imp = await impersonating();
50	  if (imp) redirect("/dashboard"); // exit impersonation before using staff tools
51	
52	  // Per-employee IP allow-list: refuses access from an IP that isn't explicitly
53	  // allowed for THIS user (see lib/staff-ip.ts for the fail-open/fail-closed
54	  // rule). An ADMIN previewing the portal has no StaffIpAllow rows, so this is a
55	  // no-op for them.
56	  if (await staffIpBlocked(user.id)) {
57	    return (
58	      <main
59	        style={{
60	          minHeight: "100vh",
61	          display: "flex",
62	          flexDirection: "column",
63	          alignItems: "center",
64	          justifyContent: "center",
65	          gap: "0.75rem",
66	          padding: "2rem",
67	          textAlign: "center",
68	        }}
69	      >
70	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Access restricted</h1>
71	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>
72	          The staff portal isn&apos;t available from your current network.
73	        </p>
74	      </main>
75	    );
76	  }
77	
78	  // Staff 2FA enforcement: identical setting/redirect to app/admin/layout.tsx,
79	  // so turning it on protects both portals at once.
80	  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
81	    redirect("/dashboard/settings?require2fa=1");
82	  }
83	
84	  // ADMIN previewing the portal has no StaffGrant rows and shouldn't need any —
85	  // show every grantable area so the owner sees exactly what full access looks
86	  // like before handing any of it to an employee. An EMPLOYEE only ever sees
87	  // what they've actually been granted.
88	  const grantedAreas = user.role === "ADMIN" ? GRANTABLE_AREAS.map((a) => a.area) : await listGrantedAreas(user.id);
89	
90	  const items = GRANTABLE_AREAS.filter((a) => grantedAreas.includes(a.area)).map((a) => ({
91	    label: a.label,
92	    href: a.href,
93	    icon: AREA_ICONS[a.area],
94	  }));
95	  // No section label: unlike the admin portal's many labelled groups, the
96	  // employee portal is a single flat tool list sized to whatever that person
97	  // was actually granted — often just one or two items.
98	  const nav: NavSection[] = items.length > 0 ? [{ key: "staff", items }] : [];
99	
100	  const notifications = await db.notification.findMany({
101	    where: { userId: user.id },
102	    orderBy: { createdAt: "desc" },
103	    take: 15,
104	  });
105	
106	  return (
107	    <Shell
108	      nav={nav}
109	      tag="staff"
110	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
111	      notifications={notifications.map((n) => ({
112	        id: n.id,
113	        title: n.title,
114	        body: n.body,
115	        href: n.href,
116	        readAt: n.readAt ? n.readAt.toISOString() : null,
117	        createdAt: n.createdAt.toISOString(),
118	      }))}
119	    >
120	      {children}
121	    </Shell>
122	  );
123	}
