1	import { requireAreaOrGrant } from "@/lib/staff-grants";
2	import { listBoards, getBoard, listAssignableUsers } from "@/lib/actions-work";
3	import { WorkBoardsView } from "@/components/work/WorkBoardsView";
4	
5	export const dynamic = "force-dynamic";
6	
7	/**
8	 * Employee-portal surface for the staff task/project system.
9	 * `requireAreaOrGrant("tasks")` redirects to /login if signed out, /dashboard
10	 * if not staff/employee, and /staff if this specific EMPLOYEE lacks the
11	 * "tasks" StaffGrant — identical gate to app/admin/tasks/page.tsx, sharing
12	 * the same WorkBoardsView/WorkBoardClient components. Renders inside
13	 * app/staff/layout.tsx's shell (owned by a separate task in this same
14	 * feature) once that lands.
15	 */
16	export default async function StaffTasksPage({
17	  searchParams,
18	}: {
19	  searchParams: Promise<{ board?: string; task?: string }>;
20	}) {
21	  await requireAreaOrGrant("tasks");
22	  const sp = await searchParams;
23	
24	  const boards = await listBoards();
25	  const activeBoardId = boards.find((b) => b.id === sp.board)?.id ?? boards[0]?.id ?? "";
26	
27	  const [board, assignableUsers] = await Promise.all([
28	    activeBoardId ? getBoard(activeBoardId) : Promise.resolve(null),
29	    listAssignableUsers(),
30	  ]);
31	
32	  return (
33	    <WorkBoardsView
34	      portal="staff"
35	      boards={boards}
36	      activeBoardId={activeBoardId}
37	      board={board}
38	      initialTaskId={sp.task ?? null}
39	      assignableUsers={assignableUsers}
40	    />
41	  );
42	}
