1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { db } from "./db";
5	import { requireAdmin } from "./auth";
6	import { requireAnyGrant } from "./staff-grants";
7	
8	const PATH = "/admin/canned-replies";
9	
10	// Same access model as the tools these snippets are used from: a granted
11	// EMPLOYEE reads/writes exactly like existing SUPPORT/ADMIN staff, via
12	// requireAnyGrant's canAccess() fast path — no separate area of its own.
13	const REPLY_AREAS = ["supportTickets", "liveChat"] as const;
14	
15	export type CannedReplyItem = {
16	  id: string;
17	  title: string;
18	  body: string;
19	  createdAt: string;
20	  updatedAt: string;
21	  createdBy: { name: string; email: string } | null;
22	};
23	
24	export async function listCannedReplies(): Promise<CannedReplyItem[]> {
25	  await requireAnyGrant([...REPLY_AREAS]);
26	  const rows = await db.cannedReply.findMany({
27	    orderBy: { title: "asc" },
28	    include: { createdBy: { select: { name: true, email: true } } },
29	  });
30	  return rows.map((r) => ({
31	    id: r.id,
32	    title: r.title,
33	    body: r.body,
34	    createdAt: r.createdAt.toISOString(),
35	    updatedAt: r.updatedAt.toISOString(),
36	    createdBy: r.createdBy ? { name: r.createdBy.name, email: r.createdBy.email } : null,
37	  }));
38	}
39	
40	export async function createCannedReply(title: string, body: string): Promise<{ id?: string; error?: string }> {
41	  const user = await requireAnyGrant([...REPLY_AREAS]);
42	  const cleanTitle = String(title ?? "").trim().slice(0, 120);
43	  const cleanBody = String(body ?? "").trim();
44	  if (!cleanTitle) return { error: "Enter a title." };
45	  if (!cleanBody) return { error: "Enter the reply text." };
46	  if (cleanBody.length > 5000) return { error: "Reply is too long (5000 char max)." };
47	
48	  const reply = await db.cannedReply.create({
49	    data: { title: cleanTitle, body: cleanBody, createdById: user.id },
50	  });
51	  revalidatePath(PATH);
52	  return { id: reply.id };
53	}
54	
55	export async function updateCannedReply(id: string, title: string, body: string): Promise<{ error?: string }> {
56	  await requireAnyGrant([...REPLY_AREAS]);
57	  const cleanTitle = String(title ?? "").trim().slice(0, 120);
58	  const cleanBody = String(body ?? "").trim();
59	  if (!cleanTitle) return { error: "Enter a title." };
60	  if (!cleanBody) return { error: "Enter the reply text." };
61	  if (cleanBody.length > 5000) return { error: "Reply is too long (5000 char max)." };
62	
63	  await db.cannedReply
64	    .update({ where: { id }, data: { title: cleanTitle, body: cleanBody } })
65	    .catch(() => undefined);
66	  revalidatePath(PATH);
67	  return {};
68	}
69	
70	/**
71	 * Delete stays ADMIN-only rather than following create/edit's grant gate —
72	 * a shared snippet library is low-stakes either way, but a support agent
73	 * wiping a reply teammates rely on (by accident or after a dispute) is a
74	 * worse failure mode than one they didn't author sitting around unused.
75	 * Picking the safer default since nothing forces this choice either way.
76	 */
77	export async function deleteCannedReply(id: string): Promise<void> {
78	  await requireAdmin();
79	  await db.cannedReply.delete({ where: { id } }).catch(() => undefined);
80	  revalidatePath(PATH);
81	}
