export async function SupportTicketView({ id, currentUserId }: { id: string; currentUserId: string }) {
  const ticket = await db.ticket.findUnique({
    where: { id },
    include: {
      messages: {
        select: {
          id: true,
          body: true,
          isStaff: true,
          authorId: true,
          createdAt: true,
          readAt: true,
          editedAt: true,
          attachmentMime: true,
          attachmentName: true,
          attachmentSize: true,
          author: { select: { name: true, role: true } },
        },
        orderBy: { createdAt: "asc" },
      },
      user: {
        select: {
          id: true,
          name: true,
          email: true,
          balanceCents: true,
          createdAt: true,
          suspended: true,
          _count: { select: { servers: true, tickets: true } },
        },
      },
    },
  });
  if (!ticket) notFound();

  const closed = ticket.status === "CLOSED";

  return (
    // Layout note: below `xl` this is just a normal stacked, page-scrolling
    // column (unchanged from before). At `xl` and up it becomes a height-capped
    // flex column — `8rem` accounts for the portal Shell's own sticky 64px
    // topbar plus this route's `py-8` main padding — so that NEITHER the ticket
    // header below NOR the right-hand customer/notes panel ever scroll: only
    // the message thread (its own `overflow-y-auto` region) does. This is the
    // "sidebar column just doesn't scroll" restructure rather than a `sticky`
    // one, because it needs no top-offset math to keep two stacked sticky bars
    // (Shell's + this page's) from overlapping.
    <div className="flex flex-col gap-4 xl:h-[calc(100vh-8rem)]">
      <div className="shrink-0">
        <PageHeader title={ticket.subject} sub={`Ticket opened ${ticket.createdAt.toISOString().slice(0, 10)} · updated ${timeAgo(ticket.updatedAt)}`}>
          <StatusDot status={ticket.status} />
          <PrioritySelect ticketId={ticket.id} priority={ticket.priority} />
          <TicketStatusButton ticketId={ticket.id} closed={closed} />
        </PageHeader>
      </div>

      <div className="grid flex-1 gap-4 xl:grid-cols-3 xl:overflow-hidden">
        {/* Thread — the ONLY region that scrolls at xl+ */}
        <div className="flex flex-col gap-4 xl:col-span-2 xl:overflow-hidden">
          <div className="space-y-4 xl:flex-1 xl:overflow-y-auto xl:pr-1">
            {ticket.messages.map((m) => (
              <div key={m.id} className={`flex ${m.isStaff ? "justify-end" : "justify-start"}`}>
                <div className="max-w-[85%]">
                  <div
                    className={`rounded-2xl px-4 py-3 text-sm ${
                      m.isStaff
                        ? "border border-brand-500/30 bg-brand-500/10"
                        : "glass border border-white/[0.08]"
                    }`}
                  >
                    <div className="mb-1.5 flex items-center gap-2 text-xs text-slate-400">
                      <span className="font-medium text-slate-300">{m.author.name}</span>
                      {m.isStaff && <Badge tone="brand">staff</Badge>}
                      <span>{timeAgo(m.createdAt)}</span>
                    </div>
                    <EditableMessageBody
                      messageId={m.id}
                      initialBody={m.body}
                      createdAtIso={m.createdAt.toISOString()}
                      editedAtIso={m.editedAt?.toISOString() ?? null}
                      canEditPermission={m.authorId === currentUserId && !closed}
                      bodyClassName="whitespace-pre-wrap leading-relaxed"
                    />
                    {m.attachmentMime && m.attachmentName && (
                      <MessageAttachment
                        messageId={m.id}
                        mime={m.attachmentMime}
                        name={m.attachmentName}
                        size={m.attachmentSize ?? 0}
                      />
                    )}
                  </div>
                  {/* Read receipt: staff -> customer visibility only, never rendered
                      on the customer-facing thread. */}
                  {m.isStaff && (
                    <div className="mt-1 flex justify-end">
                      <ReadReceipt readAt={m.readAt} />
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>

          <div className="card shrink-0">
            <h2 className="mb-3 font-semibold">Reply as staff</h2>
            {closed ? (
              <p className="text-sm text-slate-500">
                This ticket is closed — reopen it above to continue the conversation.
              </p>
            ) : (
              <ReplyForm ticketId={ticket.id} />
            )}
          </div>
        </div>

        {/* Customer context — stays put while the thread scrolls */}
        <div className="space-y-4 xl:overflow-y-auto">
          <div className="card">
            <h2 className="mb-4 font-semibold">Customer</h2>
            <dl className="space-y-2.5 text-sm">
              <div className="flex justify-between gap-3">
                <dt className="text-slate-500">Name</dt>
                <dd className="text-right">
                  <Link href={`/admin/users/${ticket.user.id}`} className="font-medium hover:text-brand-300">
                    {ticket.user.name}
                  </Link>
                  {ticket.user.suspended && (
                    <span className="ml-2">
                      <Badge tone="red">suspended</Badge>
                    </span>
                  )}
                </dd>
              </div>
              <div className="flex justify-between gap-3">
                <dt className="text-slate-500">Email</dt>
                <dd className="truncate text-right">
                  <Link href={`/admin/users/${ticket.user.id}`} className="hover:text-brand-300">
                    {ticket.user.email}
                  </Link>
                </dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Wallet balance</dt>
                <dd>{fmtMoney(ticket.user.balanceCents)}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Servers</dt>
                <dd>{ticket.user._count.servers}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Tickets total</dt>
                <dd>{ticket.user._count.tickets}</dd>
              </div>
              <div className="flex justify-between">
                <dt className="text-slate-500">Joined</dt>
                <dd>{ticket.user.createdAt.toISOString().slice(0, 10)}</dd>
              </div>
            </dl>
            <Link href={`/admin/users/${ticket.user.id}`} className="btn-secondary mt-4 w-full text-center">
              Open customer 360 →
            </Link>
          </div>

          <div className="card">
            <h2 className="mb-2 font-semibold">Handling notes</h2>
            <p className="text-xs leading-relaxed text-slate-500">
              Staff replies mark the ticket ANSWERED and notify the customer. A customer reply flips it back to
              needs-attention. Closing is reversible at any time.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

