"use client";

import { useEffect, useState } from "react";
import { listCannedReplies, type CannedReplyItem } from "@/lib/actions-canned-replies";

/**
 * Quick-replies snippet picker, shared between the ticket reply form
 * (components/admin/TicketControls.tsx) and the live-chat reply box
 * (components/admin/ChatInbox.tsx). v1 on purpose: a plain `<select>` that
 * appends the chosen snippet's body onto whatever the agent has already
 * typed — no rich-text merge, no keyboard-shortcut trigger. The list loads
 * client-side via `listCannedReplies` (already gated
 * requireAnyGrant(["supportTickets","liveChat"]) in
 * lib/actions-canned-replies.ts), so this renders nothing extra for a caller
 * who somehow reaches it without either grant — the action call simply
 * throws and the catch below leaves the picker empty rather than crashing
 * the reply box around it.
 */
export function CannedReplyPicker({
  onInsert,
  disabled,
}: {
  onInsert: (body: string) => void;
  disabled?: boolean;
}) {
  const [replies, setReplies] = useState<CannedReplyItem[]>([]);

  useEffect(() => {
    let alive = true;
    listCannedReplies()
      .then((rows) => alive && setReplies(rows))
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, []);

  if (replies.length === 0) return null;

  return (
    <select
      aria-label="Insert a canned reply"
      className="input w-auto py-1.5 text-xs"
      value=""
      disabled={disabled}
      onChange={(e) => {
        const reply = replies.find((r) => r.id === e.target.value);
        if (reply) onInsert(reply.body);
        e.target.value = "";
      }}
    >
      <option value="" disabled>
        Insert canned reply…
      </option>
      {replies.map((r) => (
        <option key={r.id} value={r.id}>
          {r.title}
        </option>
      ))}
    </select>
  );
}

