import { db } from "@/lib/db";
import { readTyping } from "@/lib/chat-typing";
import { PageHeader, StatCard } from "@/components/ui/primitives";
import ChatInbox from "@/components/admin/ChatInbox";

/**
 * Live-chat inbox. Shared verbatim between the admin ops portal
 * (app/admin/chat/page.tsx) and the employee portal (app/staff/chat/page.tsx)
 * — both gate with requireAreaOrGrant("liveChat") before rendering this, so
 * a granted EMPLOYEE sees exactly the same conversations and can reply the
 * same way SUPPORT/ADMIN staff do. ChatInbox itself carries no admin-only
 * links or props — its one deep-link action (transfer to ticket) is routed
 * by the acting user's role inside lib/actions-chat.ts, not by anything
 * passed down from here.
 */
export async function ChatDeskView() {
  // Stat totals come from COUNTs over the whole table, not from `rows` — the inbox
  // list is capped at 200, and deriving "Open"/"Unread"/"Total" from that capped
  // set silently under-reports the moment there are more than 200 conversations.
  const [rows, openCount, unreadCount, totalCount] = await Promise.all([
    db.chatConversation.findMany({
      orderBy: [{ unreadForAgent: "desc" }, { lastMessageAt: "desc" }],
      take: 200,
      include: { messages: { orderBy: { createdAt: "asc" } } },
    }),
    db.chatConversation.count({ where: { status: "OPEN" } }),
    db.chatConversation.count({ where: { unreadForAgent: true } }),
    db.chatConversation.count(),
  ]);

  // Resolve the staff names handling assigned conversations, in one query, so the
  // thread view can label each human reply with the agent's name from first paint.
  const staffIds = Array.from(
    new Set(rows.map((c) => c.assignedToId).filter((v): v is string => !!v))
  );
  const staff = staffIds.length
    ? await db.user.findMany({ where: { id: { in: staffIds } }, select: { id: true, name: true } })
    : [];
  const staffNames = new Map(staff.map((u) => [u.id, u.name]));

  const initial = rows.map((c) => ({
    id: c.id,
    visitorId: c.visitorId,
    userId: c.userId,
    name: c.name,
    email: c.email,
    status: c.status,
    assignedToId: c.assignedToId,
    assignedToName: c.assignedToId ? staffNames.get(c.assignedToId) ?? null : null,
    unreadForAgent: c.unreadForAgent,
    lastMessageAt: c.lastMessageAt.toISOString(),
    createdAt: c.createdAt.toISOString(),
    visitorTyping: readTyping(c.id).visitor,
    aiPaused: c.aiPaused,
    messages: c.messages.map((m) => ({
      id: m.id,
      sender: m.sender,
      body: m.body,
      createdAt: m.createdAt.toISOString(),
    })),
  }));

  return (
    <div className="space-y-6">
      <PageHeader title="Live chat" sub="Real-time conversations from the site widget." />

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-3">
        <StatCard label="Open" value={String(openCount)} />
        <StatCard label="Unread" value={String(unreadCount)} delta={unreadCount > 0 ? "needs a reply" : "all caught up"} deltaGood={unreadCount === 0} />
        <StatCard label="Total" value={String(totalCount)} />
      </div>

      <ChatInbox initial={initial} />
    </div>
  );
}

