import Link from "next/link";
import { PageHeader } from "@/components/ui/primitives";
import type { MailFolder, MailboxInfo, ListResult } from "@/lib/mail/types";
import { listFolders, listMessages } from "@/lib/actions-mail";
import { listCompanyMailboxes, listCompanyMailboxInfos } from "@/lib/actions-company-mail";
import { MailClient } from "@/components/customer/mail/MailClient";

/**
 * In-portal webmail for the company mailboxes (admin@, support@, santino@, …).
 * Shared verbatim between the admin ops portal (app/admin/inbox/page.tsx) and
 * the employee portal (app/staff/inbox/page.tsx) — both gate with
 * requireAreaOrGrant("companyInbox") before rendering this. Reading works
 * because resolveMailbox has a staff/grant-aware branch that resolves
 * CompanyMailboxes (see lib/mail/imap.ts). `mailboxesHref` only changes where
 * the "manage mailboxes" links point — /admin/mailboxes for the ops portal,
 * /staff/mailboxes for the employee portal (only reachable there if that
 * specific EMPLOYEE also holds the companyMailboxes grant; if not, the link
 * simply 403s them same as hand-typing the URL would).
 */
export async function CompanyInboxView({
  requestedMailbox,
  mailboxesHref,
}: {
  requestedMailbox?: string;
  mailboxesHref: string;
}) {
  const company = await listCompanyMailboxes();
  if (company.length === 0) {
    return (
      <div className="space-y-6">
        <PageHeader title="Company inbox" sub="Read and send from the company mailboxes." />
        <div className="card flex flex-col items-center justify-center py-14 text-center">
          <h3 className="text-base font-semibold">No mailboxes yet</h3>
          <p className="mt-1 max-w-sm text-sm text-slate-400">
            Create a company mailbox first, then read its mail here.
          </p>
          <Link href={mailboxesHref} className="btn-primary mt-5">
            Manage mailboxes
          </Link>
        </div>
      </div>
    );
  }

  // The switcher shows only the company mailboxes (with their live quota usage).
  const mailboxes: MailboxInfo[] = company.map((c) => ({
    address: c.address,
    usedBytes: (c.usedMB ?? 0) * 1024 * 1024,
    quotaBytes: c.quotaMB * 1024 * 1024,
  }));

  // Which mailbox to open first. Honour `?mailbox=` when it names a real company
  // mailbox; otherwise start on the first one (listCompanyMailboxes orders by
  // address asc, so this is stable). We then try that mailbox and — if it can't
  // be reached — fall back to the remaining ones IN ORDER.
  //
  // WHY the fallback: a company mailbox that can't be opened (its Mailcow
  // password was rotated out-of-band, the box is mid-provision, a transient IMAP
  // hiccup) used to dead-end the WHOLE inbox on the error card below — even
  // though there are three other perfectly readable company mailboxes. One bad
  // default made every company mailbox unreadable in the portal. Landing on the
  // first mailbox that actually loads keeps the inbox usable; the switcher
  // still lists them all, so staff can jump to any specific one.
  const wanted = requestedMailbox?.trim().toLowerCase();
  const preferred =
    wanted && mailboxes.some((m) => m.address.toLowerCase() === wanted) ? wanted : mailboxes[0].address;
  const candidates = [preferred, ...mailboxes.map((m) => m.address).filter((a) => a !== preferred)];

  let active = preferred;
  let folders: MailFolder[] = [];
  let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
  let inboxPath = "INBOX";

  for (const address of candidates) {
    try {
      const f = await listFolders(address);
      if (f.length === 0) continue;
      const path = f.find((x) => x.role === "inbox")?.path ?? f[0]?.path ?? "INBOX";
      const msgs = await listMessages(path, 1, undefined, address);
      active = address;
      folders = f;
      inboxPath = path;
      list = msgs;
      break;
    } catch {
      // Try the next company mailbox; only report failure if none load.
    }
  }

  if (folders.length === 0) {
    return (
      <div className="space-y-6">
        <PageHeader title="Company inbox" sub={preferred} />
        <div className="card p-6 text-center text-sm text-slate-400">
          Couldn&apos;t reach the mail server for any company mailbox.
          If a mailbox was just created, give it a moment and reload; otherwise reset its password on the{" "}
          <Link href={mailboxesHref} className="text-brand-300 hover:underline">
            Mailboxes
          </Link>{" "}
          page.
        </div>
      </div>
    );
  }

  // The content area is full-bleed (Shell renders /admin/inbox and /staff/inbox
  // in an `overflow-hidden flex-1` <main>, see components/portal/Shell.tsx).
  // Sizing to the viewport minus the header (4rem) plus a small margin keeps the
  // whole mail surface inside the content area; MailClient is `h-full`
  // internally and scrolls its own panes.
  //
  // NOTE: the admin ops portal additionally stacks an <AdminSubTabs> bar above
  // this component inside that same <main> (Inbox / Deliverability / Mailboxes
  // / Email templates), which is why app/admin/inbox/page.tsx historically sized
  // this to `calc(100vh-8.5rem)`. The employee portal has no such sub-tab bar,
  // so it sizes to `calc(100vh-4.5rem)` (matching /staff/reddit's own full-bleed
  // sizing) instead — this component doesn't know which portal it's in, so both
  // callers wrap it with their own height, not this component itself.
  return (
    <MailClient
      initialFolders={folders}
      initialMailboxes={mailboxes}
      initialList={list}
      initialFolderPath={inboxPath}
      initialActiveAddress={active}
      loadMailboxes={listCompanyMailboxInfos}
    />
  );
}

import { requireAreaOrGrant } from "@/lib/staff-grants";
import { CompanyInboxView } from "@/components/admin/CompanyInboxView";

export const dynamic = "force-dynamic";
export const metadata = { title: "Company inbox" };

