import { PageHeader } from "@/components/ui/primitives";

export type ClientBasicRow = {
  id: string;
  name: string;
  email: string;
  createdAt: Date;
  _count: { tickets: number; servers: number };
};

/**
 * Read-only client list — the single most security-critical component in the
 * staff-platform plan. It renders ONLY what its caller (app/staff/clients
 * /page.tsx and its admin preview at app/admin/clients-basic/page.tsx) hands
 * it: name, email, signup date, ticket count, server count. There is no
 * per-row action of any kind here — no impersonate, no suspend, no credit,
 * no link into a fuller customer profile — by design, not by omission. The
 * real guarantee lives one layer up, in the Prisma `select` those two pages
 * use: this component never even RECEIVES balance/IP/audit/note data to
 * accidentally render, because "a control a role cannot use is not a
 * permission, it is a promise the server refuses to keep" (see
 * app/admin/users/[id]/page.tsx).
 */
export function ClientsBasicView({ clients }: { clients: ClientBasicRow[] }) {
  return (
    <div className="space-y-6">
      <PageHeader
        title="Clients"
        sub="Name, email, signup date, and ticket/server counts only — no financials, no IP history, no audit trail."
      />

      <div className="card overflow-x-auto p-0">
        <table className="table-shell">
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Signed up</th>
              <th className="text-right">Tickets</th>
              <th className="text-right">Servers</th>
            </tr>
          </thead>
          <tbody>
            {clients.length === 0 && (
              <tr>
                <td colSpan={5} className="py-10 text-center text-slate-500">
                  No clients yet.
                </td>
              </tr>
            )}
            {clients.map((c) => (
              <tr key={c.id}>
                <td className="font-medium">{c.name}</td>
                <td className="text-slate-300">{c.email}</td>
                <td className="text-xs text-slate-400">{c.createdAt.toISOString().slice(0, 10)}</td>
                <td className="text-right">{c._count.tickets}</td>
                <td className="text-right">{c._count.servers}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { requireAreaOrGrant } from "@/lib/staff-grants";
