import { ClientsBasicView } from "@/components/staff/ClientsBasicView";

export const dynamic = "force-dynamic";

/**
 * The single most security-critical route in the staff-platform plan: a
 * granted EMPLOYEE's ENTIRE view of customers. The `select` below is the real
 * guarantee, not the component it feeds — it is scoped to exactly
 * id/name/email/createdAt plus `_count` on tickets/servers and NOTHING else.
 * No `balanceCents`, no wallet/invoice relation, no IP/geolocation
 * (`Visit`), no `AuditLog`, no `CustomerNote` — those fields are never
 * fetched from the database in the first place, so there is nothing for a
 * future edit to this page to accidentally render. See
 * components/staff/ClientsBasicView.tsx for the read-only rendering half of
 * this guarantee, and app/admin/clients-basic/page.tsx for the ADMIN-only
 * preview of this exact same query/component pair.
 */
export default async function StaffClientsPage() {
  await requireAreaOrGrant("clientsBasic");

  const clients = await db.user.findMany({
    select: {
      id: true,
      name: true,
      email: true,
      createdAt: true,
      _count: { select: { tickets: true, servers: true } },
    },
    orderBy: { createdAt: "desc" },
    take: 200,
  });

  return <ClientsBasicView clients={clients} />;
}

