import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join, extname } from "node:path";
import { stripComments } from "./_source-tools.ts";

/**
 * A signed-in customer must never learn which registrar Nxeon uses behind the
 * scenes — search results, error messages, DNS/nameserver copy, and the AI
 * chat assistant all have to stay registrar-agnostic (see the multi-registrar
 * plan's leak list). This is a standing tripwire, not a one-time fix: it scans
 * every customer-facing surface for the literal registrar names and fails the
 * moment one shows up again, whether from a careless copy change or a future
 * registrar integration (Namecheap, eNom, ...).
 *
 * `app/admin/**` is excluded on purpose — the admin console is the ONE place
 * this information is allowed, and is expected, to appear (e.g. a per-domain
 * "Registrar" column).
 *
 * Comments are stripped before matching (via `stripComments`, same helper the
 * other structural tripwires use) so an internal doc comment explaining "this
 * calls name.com's API" doesn't fail the test — only text a customer could
 * actually see (JSX, string literals, template literals) counts.
 */

const ROOT = join(import.meta.dirname, "..");
const SCAN_DIRS = ["components/customer", "app/dashboard"];
const EXTENSIONS = new Set([".ts", ".tsx"]);

// Word-boundary on "enom" so it doesn't fire on ordinary English words that
// happen to contain that substring (e.g. "denominator", "phenomenon"). A
// negative lookbehind on "name.com" so a placeholder example domain like
// "another-name.com" (a stand-in for "put your own domain here", unrelated to
// the registrar) doesn't fire either — only "name.com" as its own token does.
const FORBIDDEN: { label: string; pattern: RegExp }[] = [
  { label: "name.com", pattern: /(?<![a-z0-9-])name\.com/i },
  { label: "Namecheap", pattern: /namecheap/i },
  { label: "eNom", pattern: /\benom\b/i },
];

/**
 * A second, narrower category: phrasing that names no vendor but still tells a
 * customer "a third-party company handles Nxeon's own domain registration" —
 * e.g. "activates once the registrar integration is configured", "applied at
 * the registrar", "checking with the registrar". Nxeon's brand voice is
 * first-person-owner ("we ARE the provider"), so even a vendor-agnostic
 * implication of an external registrar behind NXEON'S OWN registrations is a
 * leak, not just a named one — this was found and fixed across 13 sites after
 * the FORBIDDEN literal-name sweep above already passed clean.
 *
 * Scoped narrowly to phrases that only ever appear when describing Nxeon's OWN
 * backend (never "your other/current/new registrar" during an inbound
 * transfer, which is a real external entity and legitimate to name). Two
 * files are excluded entirely because EVERY "registrar" mention in them refers
 * to the customer's own OTHER registrar during a transfer-in — a real company
 * Nxeon doesn't control, correctly described.
 */
const IMPLIED_THIRD_PARTY_EXCLUDE = new Set([
  "components/customer/DomainTransferIn.tsx",
  "components/customer/DomainTransferInWizard.tsx",
]);
const IMPLIED_THIRD_PARTY: { label: string; pattern: RegExp }[] = [
  { label: "the registrar integration", pattern: /the registrar integration/i },
  { label: "at the registrar", pattern: /\bat the registrar\b/i },
  { label: "with the registrar", pattern: /\bwith the registrar\b/i },
  { label: "from the registrar", pattern: /\bfrom the registrar\b/i },
  { label: "registrar API", pattern: /\bregistrar api\b/i },
  { label: "registrar lock", pattern: /\bregistrar lock\b/i },
  { label: "registrar record", pattern: /\bregistrar record\b/i },
];

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory()) walk(full, out);
    else if (EXTENSIONS.has(extname(entry))) out.push(full);
  }
  return out;
}

test("no registrar identity leaks into customer-facing dashboard/components code", () => {
  const offenders: string[] = [];
  for (const dir of SCAN_DIRS) {
    for (const file of walk(join(ROOT, dir))) {
      const src = stripComments(readFileSync(file, "utf8"));
      const rel = file.slice(ROOT.length + 1);
      for (const { label, pattern } of FORBIDDEN) {
        if (pattern.test(src)) offenders.push(`${rel} — matched "${label}"`);
      }
      if (!IMPLIED_THIRD_PARTY_EXCLUDE.has(rel)) {
        for (const { label, pattern } of IMPLIED_THIRD_PARTY) {
          if (pattern.test(src)) offenders.push(`${rel} — matched "${label}"`);
        }
      }
    }
  }
  assert.deepEqual(
    offenders,
    [],

